const b = $input.first().json.body;
const list = (Array.isArray(b) ? b : []).filter(c => c && c.id).slice(0, 10);
const base = $env.CAMPAIGNS_URL;
return list.length ? list.map(c => ({ json: { url: `${base}/campaigns/${c.id}/scorecard` } }))
                   : [{ json: { url: `${base}/health`, noop: true } }];

const cards = $input.all().map(i => i.json.body).filter(b => b && typeof b === 'object' && b.campaign);
return [{ json: { scorecards: cards.map(c => ({ campaign: c.campaign.name, elapsed_pct: c.elapsed_pct,
  kpis: (c.kpis || []).map(k => ({ metric: k.metric, target: k.target_value, actual: k.actual_value,
    progress_pct: k.progress_pct, state: k.state })) })) } }];

const b = $input.first().json.body;
const list = $env.ENGINE_URL && Array.isArray(b) ? b.filter(p => p && p.id).slice(0, 10) : [];
return list.length ? list.map(p => ({ json: { url: `${$env.ENGINE_URL}/pillars/${p.id}/health`, title: p.title } }))
                   : [{ json: { url: `${$env.CAMPAIGNS_URL}/health`, noop: true } }];

// One compact JSON for the weekly_actions prompt. Every part is optional: a source that
// failed (or is not configured) is left out, never invented.
const lw = $('Last week').first().json;
const body = n => { try { const b = $(n).first().json.body; return b && typeof b === 'object' ? b : null; } catch (e) { return null; } };
const data = {};
const k = $('KPIs').first().json;
if (k && k.totals) {
  data.kpis = { totals: k.totals, delta_pct: k.delta_pct || null,
    by_channel: (k.by_channel || []).map(c => ({ channel: c.channel, sessions: c.sessions, clicks: c.clicks,
      conversions: c.conversions, cvr: c.cvr })) };
}
const ins = body('Clicks by channel');
if (ins && ((ins.by_channel || []).length || (ins.top_posts || []).length)) {
  data.clicks = { days: 7, by_channel: ins.by_channel || [],
    top_posts: (ins.top_posts || []).slice(0, 5).map(p => ({ title: p.title, channel: p.channel, clicks: p.clicks })) };
}
const hk = body('Winning hooks');
if (hk && Array.isArray(hk.styles)) {
  const used = hk.styles.filter(s => s.posts > 0)
    .map(s => ({ hook_style: s.hook_style, posts: s.posts, clicks: s.clicks, clicks_per_post: s.clicks_per_post }));
  if (used.length) data.hooks = { days: 90, styles: used };
}
const cards = $('Collect scorecards').first().json.scorecards || [];
if (cards.length) data.campaigns = cards;
const titles = $('One per pillar').all().map(i => i.json.title);
const pillars = $('Pillar health').all().map((i, n) => ({ b: i.json.body, title: titles[n] }))
  .filter(x => x.b && typeof x.b === 'object' && x.b.pillar_id)
  .map(({ b, title }) => ({ pillar: title, decided: b.decided, approved: b.approved, edited: b.edited, rejected: b.rejected,
    approved_clean_rate: b.approved_clean_rate, rejected_rate: b.rejected_rate, paused: b.paused, reason: b.reason || null }));
if (pillars.length) data.pillars = pillars;
// Comparisons worked out in code. The 7B model combined real numbers into wrong statements
// ("sessions decreased by 1,015 to 1,855"); with finished sentences it only has to quote.
const facts = [];
const fmt = n => typeof n === 'number' ? (Number.isInteger(n) ? n.toLocaleString('en-US') : String(Math.round(n * 1000) / 1000)) : String(n);
if (k && k.totals) {
  const prev = (k.previous || {}).totals || {};
  for (const [m, v] of Object.entries(k.totals)) {
    if (typeof v !== 'number') continue;
    const d = (k.delta_pct || {})[m];
    facts.push(`${m}: ${fmt(v)} last week` + (typeof prev[m] === 'number' ? `, ${fmt(prev[m])} the week before` : '')
      + (typeof d === 'number' ? ` (${d > 0 ? '+' : ''}${fmt(d)}%)` : ''));
  }
}
for (const c of (data.clicks || {}).by_channel || []) facts.push(`${c.channel}: ${fmt(c.clicks)} tracked clicks from ${fmt(c.posts)} posts last week`);
for (const h of (data.hooks || {}).styles || []) facts.push(`hook "${h.hook_style}": ${fmt(h.clicks_per_post)} clicks per post over ${fmt(h.posts)} posts (90 days)`);
if (facts.length) data.facts = facts;
return [{ json: { data: JSON.stringify(data), period: `${lw.from} to ${lw.to}`, parts: Object.keys(data) } }];

// Numbers are the part a small model invents. Every number in an action's "why" must appear
// in the data it was given (thousands separators and the sign are ignored), or the action is
// dropped; an action without any number is dropped too. At most one action per channel.
// Headline and what-changed lines with a number that is not in the data are removed.
const src = $('Action data').first().json;
const nums = s => (String(s).replace(/(\d),(?=\d{3}\b)/g, '$1').match(/\d+(?:\.\d+)?/g) || []).map(Number);
const known = new Set(nums(src.data + ' ' + src.period));
const supported = s => nums(s).every(x => known.has(x));
const g = $input.first().json;
const o = g && g.output && typeof g.output === 'object' ? g.output : null;
if (!o) {
  const why = (g && g.error && (g.error.message || g.error)) || 'no output';
  return [{ json: { markdown: '', actions: [], dropped: [], note: `next actions skipped: ${String(why).slice(0, 200)}` } }];
}
const dropped = [], seen = new Set(), actions = [];
for (const a of Array.isArray(o.actions) ? o.actions : []) {
  const ch = String(a.channel || '').trim(), key = ch.toLowerCase();
  const reason = !ch || !a.action ? 'empty'
    : !nums(a.why).length ? 'why cites no number'
    : !supported(a.why) ? `number not in the data (${nums(a.why).filter(x => !known.has(x)).join(', ')})`
    : seen.has(key) ? 'second action for the channel' : '';
  if (reason) { dropped.push({ ...a, reason }); continue; }
  seen.add(key);
  actions.push({ channel: ch, action: String(a.action).slice(0, 140), why: String(a.why) });
}
const changed = (Array.isArray(o.what_changed) ? o.what_changed : []).filter(supported).slice(0, 4);
const headline = o.headline && supported(o.headline) ? o.headline : '';
// Blocks separated by a blank line, so the two lists render as two lists.
const md = ['### Next actions',
  headline ? `**${headline}**` : '',
  changed.length ? ['What changed:', '', ...changed.map(c => `- ${c}`)].join('\n') : '',
  ['One next action per channel:', '',
   ...(actions.length ? actions.map(a => `- **${a.channel}**: ${a.action.replace(/\.$/, '')}. _Why:_ ${a.why}`)
                      : ['- None this week: no suggestion was backed by a number in the data.'])].join('\n'),
  dropped.length ? `_${dropped.length} suggestion${dropped.length === 1 ? ' was' : 's were'} dropped: ${dropped.map(d => `${d.channel || '?'} (${d.reason})`).join('; ')}._` : '',
].filter(Boolean).join('\n\n');
return [{ json: { markdown: md, headline, what_changed: changed, actions, dropped, parts: src.parts } }];

const listOf = n => { try { const raw = [].concat($(n).first().json.body ?? []);
  return (raw.length === 1 && Array.isArray(raw[0]) ? raw[0] : raw).filter(x => x && x.id); } catch (e) { return []; } };

// Appended to the next-actions markdown: running, decided and no-difference experiments.
const md = $('Check actions').first().json.markdown || '';
const exps = listOf('Experiments');
if (!exps.length) return [{ json: { ...$('Check actions').first().json, markdown: md } }];
const arms = e => (e.arms || []).map(a => `${a.label} ${a.value}`).join(' vs ');
const run = exps.filter(e => e.status === 'running');
const dec = exps.filter(e => e.status === 'decided').sort((a, b) => String(b.decided_at).localeCompare(String(a.decided_at))).slice(0, 8);
const wait = exps.filter(e => ['proposed', 'approved'].includes(e.status));
const lines = ['### Experiments'];
if (run.length) lines.push('Running:', '', ...run.map(e => `- #${e.id} ${e.variable} on ${e.channels.join(', ')}: ${arms(e)}; ` +
  `${e.assigned.A} + ${e.assigned.B} posts assigned, next look ${String(e.next_look_at || '?').slice(0, 10)}`), '');
const verdict = e => e.decision === 'winner' ? `**${e.winner.value}** beat ${e.loser.value}`
  : e.decision === 'no_practical_difference' ? 'no practical difference: the choice is free' : 'inconclusive';
const winners = dec.filter(e => e.decision === 'winner'), nodiff = dec.filter(e => e.decision !== 'winner');
if (winners.length) lines.push('Decided:', '', ...winners.map(e => `- #${e.id} ${e.variable} on ${e.channels.join(', ')}: ${verdict(e)} (${String(e.decided_at).slice(0, 10)}; a rule needs a second experiment that agrees)`), '');
if (nodiff.length) lines.push('No difference or inconclusive:', '', ...nodiff.map(e => `- #${e.id} ${e.variable} on ${e.channels.join(', ')}, ${arms(e)}: ${verdict(e)} (${String(e.decided_at).slice(0, 10)})`), '');
if (wait.length) lines.push(`${wait.length} proposed or approved, not started yet.`);
return [{ json: { ...$('Check actions').first().json, markdown: [md, lines.join('\n').trim()].filter(Boolean).join('\n\n') } }];

const prev = $('Experiments section').first().json;
const r = $input.first().json || {};
const b = $env.AD_LIBRARY_URL && r.statusCode >= 200 && r.statusCode < 300 && r.body && typeof r.body === 'object' ? r.body : null;
if (!b || !b.pending) return [{ json: prev }];
const fresh = (b.new || []).map(n => `${n.name} (${n.mentions} mentions)`);
const lines = ['### Competitor suggestions',
  `${b.pending} website(s) our reviews, social mentions or trend digests keep naming are waiting for you` +
  (fresh.length ? `; new this week: ${fresh.slice(0, 5).join(', ')}` : '') + '.',
  'See them with the quotes: `GET /suggestions` on ad-library-sync (78). Track one: ' +
  '`POST /competitors/<name>/status {"status":"active"}`; drop it: `{"status":"ignored"}`.'];
return [{ json: { ...prev, markdown: [prev.markdown, lines.join('\n')].filter(Boolean).join('\n\n') } }];

function notifyRequest(text, env, waits) {
  const fmt = String(env.NOTIFY_FORMAT || 'generic').trim().toLowerCase();
  const telegram = fmt === 'telegram';
  if (telegram ? !(env.TELEGRAM_BOT_TOKEN && env.TELEGRAM_CHAT_ID) : !env.NOTIFY_WEBHOOK_URL) return null;
  const plain = String(text ?? '');
  const form = `${String(env.N8N_PUBLIC_URL || 'http://localhost:5678/').trim().replace(/\/?$/, '/')}form/mkt-content-approval`;
  const link = waits && !plain.includes(form) ? form : null;   // already in the text: once is enough
  // Cut the text (never the link) to the longest prefix whose rendered message fits:
  // escaping can make the rendered text several times longer, so search for it.
  const fit = (render, max) => {
    if (render(plain).length <= max) return render(plain);
    let lo = 0, hi = plain.length;
    while (lo < hi) {
      const mid = Math.ceil((lo + hi) / 2);
      if (render(plain.slice(0, mid).trimEnd() + '…').length <= max) lo = mid; else hi = mid - 1;
    }
    return render(plain.slice(0, lo).trimEnd() + '…');
  };
  const mdLink = /\[([^\]\n]+)\]\((https?:\/\/[^\s)"<>]+)\)/g;
  const oneStar = /(^|[^*\w])\*(?![\s*])([^*\n]*?[^\s*])\*(?![*\w])/g;   // Slack-style *bold*
  const heading = /^#{1,6}[ \t]+(.+)$/gm;
  if (telegram) {
    const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    const render = t => esc(t)
      .replace(mdLink, '<a href="$2">$1</a>')
      .replace(/\*\*([^*\n]+)\*\*/g, '<b>$1</b>').replace(oneStar, '$1<b>$2</b>').replace(heading, '<b>$1</b>')
      + (link ? `\n\n<a href="${esc(link)}">Open the approval form</a>` : '');
    const api = String(env.TELEGRAM_API_URL || 'https://api.telegram.org').trim().replace(/\/+$/, '');
    return { format: 'telegram', url: `${api}/bot<TELEGRAM_BOT_TOKEN>/sendMessage`, body: {
      chat_id: String(env.TELEGRAM_CHAT_ID).trim(), text: fit(render, 4096), parse_mode: 'HTML',
      disable_web_page_preview: true } };
  }
  const url = '<NOTIFY_WEBHOOK_URL>';
  if (fmt === 'slack') {
    const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    const render = t => esc(t)
      .replace(mdLink, '<$2|$1>').replace(/\*\*([^*\n]+)\*\*/g, '*$1*').replace(heading, '*$1*')
      + (link ? `\n\n<${link}|Open the approval form>` : '');
    return { format: 'slack', url, body: { text: fit(render, 40000) } };
  }
  if (fmt === 'discord') {
    // <url> stops link previews; Discord bold is **x**; nothing in the text can ping anyone.
    const render = t => t.replace(oneStar, '$1**$2**').replace(/(^|\s)(https?:\/\/[^\s<>]+)/g, '$1<$2>')
      + (link ? `\n\nApproval form: <${link}>` : '');
    return { format: 'discord', url, body: { content: fit(render, 2000), allowed_mentions: { parse: [] } } };
  }
  const t = link ? `${plain.trimEnd()}\n\nApproval form: ${link}` : plain;
  return { format: 'generic', url, body: { text: t, content: t } };   // the payload before NOTIFY_FORMAT
}

return $input.all().flatMap(item => {
  const req = notifyRequest($('Render report').first().json.markdown.slice(0, 3500), $env, false);
  return req ? [{ json: req }] : [];
});
